pub(crate) struct References<'expression, 'src> {
  stack: Vec<&'expression Expression<'src>>,
}

impl<'expression, 'src> References<'expression, 'src> {
  pub(crate) fn new(root: &'expression Expression<'src>) -> Self {
    Self { stack: vec![root] }
  }
}

impl<'src> Iterator for References<'_, 'src> {
  type Item = Reference<'src>;

  fn next(&mut self) -> Option<Self::Item> {
    loop {
      match self.stack.pop()? {
        Expression::And { lhs, rhs } | Expression::Or { lhs, rhs } => {
          self.stack.push(lhs);
          self.stack.push(rhs);
        }
        Expression::Assert {
          condition:
            Condition {
              lhs,
              rhs,
              operator: _,
            },
          error,
          ..
        } => {
          self.stack.push(error);
          self.stack.push(rhs);
          self.stack.push(lhs);
        }
        Expression::Backtick { .. } | Expression::StringLiteral { .. } => {}
        Expression::Call { name, arguments } => {
          for arg in arguments.iter().rev() {
            self.stack.push(arg);
          }
          return Some(Reference::Call {
            name: *name,
            arguments: arguments.len(),
          });
        }
        Expression::Concatenation { lhs, rhs } => {
          self.stack.push(rhs);
          self.stack.push(lhs);
        }
        Expression::Conditional {
          condition:
            Condition {
              lhs,
              rhs,
              operator: _,
            },
          then,
          otherwise,
        } => {
          self.stack.push(otherwise);
          self.stack.push(then);
          self.stack.push(rhs);
          self.stack.push(lhs);
        }
        Expression::FormatString { expressions, .. } => {
          for (expression, _string) in expressions {
            self.stack.push(expression);
          }
        }
        Expression::Group { contents } => {
          self.stack.push(contents);
        }
        Expression::Join { lhs, rhs } => {
          self.stack.push(rhs);
          if let Some(lhs) = lhs {
            self.stack.push(lhs);
          }
        }
        Expression::Variable { name, .. } => return Some(Reference::Variable(*name)),
      }
    }
  }
}
use {super::*, CompileErrorKind::*};

pub(crate) struct AssignmentResolver<'src: 'run, 'run> {
  assignments: &'run Table<'src, Assignment<'src>>,
  evaluated: BTreeSet<&'src str>,
  functions: &'run Table<'src, FunctionDefinition<'src>>,
  stack: Vec<&'src str>,
}

impl<'src: 'run, 'run> AssignmentResolver<'src, 'run> {
  pub(crate) fn resolve_assignments(
    assignments: &'run Table<'src, Assignment<'src>>,
    functions: &'run Table<'src, FunctionDefinition<'src>>,
  ) -> CompileResult<'src> {
    let mut resolver = Self {
      assignments,
      evaluated: BTreeSet::new(),
      functions,
      stack: Vec::new(),
    };

    for assignment in assignments.values() {
      resolver.resolve_assignment(assignment)?;
    }

    for function in functions.values() {
      for reference in function.body.references() {
        resolver.resolve_reference(Some(&function.parameters), reference)?;
      }
    }

    Ok(())
  }

  fn resolve_assignment(&mut self, assignment: &Assignment<'src>) -> CompileResult<'src> {
    let name = assignment.name.lexeme();

    if self.evaluated.contains(name) {
      return Ok(());
    }

    self.stack.push(name);

    for reference in assignment.value.references() {
      self.resolve_reference(None, reference)?;
    }

    self.evaluated.insert(name);

    self.stack.pop();

    Ok(())
  }

  fn resolve_reference(
    &mut self,
    parameters: Option<&[(Name<'src>, Number)]>,
    reference: Reference<'src>,
  ) -> CompileResult<'src> {
    match reference {
      Reference::Call { name, arguments } => {
        Analyzer::resolve_call(self.functions, name, arguments)
      }
      Reference::Variable(name) => self.resolve_variable(parameters, name),
    }
  }

  fn resolve_variable(
    &mut self,
    parameters: Option<&[(Name<'src>, Number)]>,
    variable: Name<'src>,
  ) -> CompileResult<'src> {
    let name = variable.lexeme();

    if let Some(parameters) = parameters {
      if parameters
        .iter()
        .any(|(parameter, _number)| parameter.lexeme() == name)
      {
        return Ok(());
      }
    }

    if self.evaluated.contains(name) || constants().contains_key(name) {
      return Ok(());
    }

    if self.stack.contains(&name) {
      self.stack.push(name);
      return Err(
        self.assignments[name]
          .name
          .error(CircularVariableDependency {
            variable: name,
            circle: self.stack.clone(),
          }),
      );
    } else if let Some(assignment) = self.assignments.get(name) {
      self.resolve_assignment(assignment)?;
    } else {
      return Err(variable.error(UndefinedVariable { variable: name }));
    }

    Ok(())
  }
}

