  }

  fn run_recipe(
    arguments: &[Vec<String>],
    config: &Config,
    is_dependency: bool,
    ran: &Ran,
    recipe: &Recipe<'src>,
    scopes: &Scopes<'src, '_>,
    search: &Search,
  ) -> RunResult<'src> {
    let mutex = ran.mutex(recipe, arguments);

    let mut guard = mutex.lock().unwrap();

    if *guard {
      return Ok(());
    }

    let (module, scope, dotenv) = scopes
      .get(recipe.module_path())
      .expect("failed to retrieve scope for module");

    let context = ExecutionContext {
      config,
      dotenv,
      module,
      search,
    };

    let (outer, positional) = Evaluator::evaluate_parameters(
      arguments,
      &context,
      is_dependency,
      &recipe.parameters,
      recipe,
      scope,
    )?;

    let scope = outer.child();

    let mut evaluator = Evaluator::new(&context, BTreeMap::new(), true, &scope);

    if !config.yes && !recipe.confirm(&mut evaluator)? {
      return Err(Error::NotConfirmed {
        recipe: recipe.name(),
      });
    }

    Self::run_dependencies(
      config,
      &context,
      recipe.priors(),
      &mut evaluator,
      ran,
      recipe,
      scopes,
      search,
    )?;

    recipe.run(&context, &scope, &positional, is_dependency)?;

    Self::run_dependencies(
      config,
      &context,
      recipe.subsequents(),
      &mut evaluator,
      &Ran::default(),
      recipe,
      scopes,
      search,
    )?;

    *guard = true;

    Ok(())
  }

  fn run_dependencies<'run>(
    config: &Config,
    context: &ExecutionContext<'src, 'run>,
    dependencies: &[Dependency<'src>],
    evaluator: &mut Evaluator<'src, 'run>,
    ran: &Ran,
    recipe: &Recipe<'src>,
    scopes: &Scopes<'src, 'run>,
    search: &Search,
  ) -> RunResult<'src> {
    if context.config.no_dependencies {
      return Ok(());
    }

    let mut evaluated = Vec::new();
    for Dependency { recipe, arguments } in dependencies {
      let mut grouped = Vec::new();
      for group in arguments {
        let evaluated_group = group
          .iter()
          .map(|argument| evaluator.evaluate_expression(argument))
          .collect::<RunResult<Vec<String>>>()?;
        grouped.push(evaluated_group);
      }
      evaluated.push((recipe, grouped));
    }

    if recipe.is_parallel() {
      thread::scope::<_, RunResult>(|thread_scope| {
        let mut handles = Vec::new();
        for (recipe, arguments) in evaluated {
          handles.push(thread_scope.spawn(move || {
            Self::run_recipe(&arguments, config, true, ran, recipe, scopes, search)
          }));
        }
        for handle in handles {
          handle
            .join()
            .map_err(|_| Error::internal("parallel dependency thread panicked"))??;
        }
        Ok(())
      })?;
    } else {
      for (recipe, arguments) in evaluated {
        Self::run_recipe(&arguments, config, true, ran, recipe, scopes, search)?;
      }
    }

    Ok(())
  }

  pub(crate) fn public_modules(&self, config: &Config) -> Vec<&Justfile> {
    let mut modules = self
      .modules
      .values()
      .filter(|module| !module.private)
      .collect::<Vec<&Justfile>>();

    if config.unsorted {
      modules.sort_by_key(|module| {
        module
          .name
          .map(|name| name.token.offset)
          .unwrap_or_default()
      });
    }

    modules
  }

  pub(crate) fn public_recipes(&self, config: &Config) -> Vec<&Recipe> {
    let mut recipes = self
      .recipes
      .values()
      .map(AsRef::as_ref)
      .filter(|recipe| recipe.is_public())
      .collect::<Vec<&Recipe>>();

    if config.unsorted {
      recipes.sort_by_key(|recipe| (&recipe.import_offsets, recipe.name.offset));
    }

    recipes
  }

  pub(crate) fn public_recipes_recursive(&self, config: &Config) -> Vec<&Recipe> {
    let mut recipes = Vec::new();

    let mut stack = vec![self];
    while let Some(current) = stack.pop() {
      for recipe in current.public_recipes(config) {
        recipes.push(recipe);
      }

      for module in current.public_modules(config).into_iter().rev() {
        stack.push(module);
      }
    }

    recipes
  }

  pub(crate) fn public_aliases_recursive(&self, config: &Config) -> Vec<(&Alias, &Modulepath)> {
    let mut aliases = Vec::new();

    let mut stack = vec![self];
