pub(crate) fn constants() -> &'static BTreeMap<&'static str, &'static str> {
  static MAP: LazyLock<BTreeMap<&str, &str>> = LazyLock::new(|| {
    CONSTANTS
      .iter()
      .copied()
      .map(|(name, unix, windows, _version)| {
        (
          name,
          if cfg!(windows) {
            windows.unwrap_or(unix)
          } else {
            unix
          },
        )
      })
      .collect()
  });

  &MAP
}

